// Normalize (webhook version) — Proposal Engine
// Receives the JSON sent by the /projet page (through your Next.js API route),
// checks every field against the allowed values, and outputs the SAME clean object
// the old form version produced. Every node after this one stays unchanged.
//
// It never throws on bad data. It outputs { valid, errors, ...data } and the next
// IF node decides: valid -> continue, invalid -> Stop and Error (-> your error alert).
// The page's server already validates with the same rules; this is the second lock,
// in case anything ever reaches the webhook without going through your page.
//
// Keep the node NAMED "Normalize": later nodes read $('Normalize') by name.
// Mode: Run Once for All Items · Language: JavaScript

// ---------------------------------------------------------------------------
// ALLOWED VALUES — must match the page's options exactly.
// ---------------------------------------------------------------------------
const SECTORS = ['Restaurant', 'Immobilier', 'E-commerce', 'Autre'];

const NEEDS = {
  Restaurant: ['Commande en ligne', 'Réservation de tables', 'Menu multilingue', 'Intégration Instagram'],
  Immobilier: ['Recherche et filtres', 'Capture et qualification de leads', 'Visites virtuelles / 3D', 'Intégration CRM'],
  'E-commerce': ['Paiements', 'Multi-devises', 'Synchro des stocks', 'Relance panier abandonné'],
  Autre: [],
};

const PRODUCT_RANGES = ['Moins de 50', '50 – 500', 'Plus de 500'];
const PLATFORMS = ['Shopify', 'WooCommerce', "Aucune pour l'instant", 'Autre'];
const LANGUAGES = ['Français', 'Arabe', 'Anglais'];
const BUDGETS = [
  'Moins de 1 000 DH/mois',
  '1 000 – 2 000 DH/mois',
  '2 000 – 4 000 DH/mois',
  'Plus de 4 000 DH/mois',
];

// Max lengths: protects the AI step and the PDF from absurdly long input.
const MAX = { short: 120, goal: 1000, notes: 1000, description: 2000 };

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const errors = [];

function text(value, field, { required = false, max = MAX.short } = {}) {
  const s = typeof value === 'string' ? value.trim() : '';
  if (!s) {
    if (required) errors.push(`${field} : obligatoire`);
    return null;
  }
  if (s.length > max) errors.push(`${field} : trop long (max ${max})`);
  return s.slice(0, max);
}

function oneOf(value, field, allowed, { required = true } = {}) {
  if (value === undefined || value === null || value === '') {
    if (required) errors.push(`${field} : obligatoire`);
    return null;
  }
  if (!allowed.includes(value)) {
    errors.push(`${field} : valeur non autorisée`);
    return null;
  }
  return value;
}

function listOf(value, field, allowed) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    errors.push(`${field} : doit être une liste`);
    return [];
  }
  const clean = [...new Set(value)].filter((v) => allowed.includes(v));
  if (clean.length !== value.length) errors.push(`${field} : valeur(s) non autorisée(s)`);
  return clean;
}

function wholeNumber(value, field, { min = 0, max = 100000 } = {}) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < min || n > max) {
    errors.push(`${field} : nombre invalide`);
    return null;
  }
  return n;
}

// ---------------------------------------------------------------------------
// Validate
// ---------------------------------------------------------------------------
// The Webhook node puts the JSON payload under "body".
const b = $input.first().json.body || {};
const contact = b.contact || {};
const scope = b.scope || {};
const d = b.details || {};

const email = text(contact.email, 'email', { required: true });
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email : format invalide');

const sector = oneOf(b.sector, 'secteur', SECTORS);

let details = {};
if (sector === 'Restaurant') {
  details = {
    locations: wholeNumber(d.locations, 'établissements', { min: 1, max: 500 }),
    currentSite: text(d.currentSite, 'site actuel', { max: 200 }),
  };
} else if (sector === 'Immobilier') {
  details = {
    listings: wholeNumber(d.listings, 'biens', { min: 0, max: 100000 }),
    markets: text(d.markets, 'villes', { required: true }),
  };
} else if (sector === 'E-commerce') {
  details = {
    productRange: oneOf(d.productRange, 'nombre de produits', PRODUCT_RANGES),
    platform: oneOf(d.platform, 'plateforme', PLATFORMS),
  };
} else if (sector === 'Autre') {
  details = { description: text(d.description, 'description', { required: true, max: MAX.description }) };
}

// Deadline: a real calendar date in YYYY-MM-DD form (past or absurd dates are
// still accepted here: Price flags them for your review instead of rejecting the lead).
let deadline = null;
if (scope.deadline) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(scope.deadline) && !Number.isNaN(Date.parse(scope.deadline))) {
    deadline = scope.deadline;
  } else {
    errors.push('date de lancement : format invalide');
  }
}

const data = {
  // Set here, not by the browser: the server's clock is the one you can trust.
  submittedAt: new Date().toISOString(),
  isTest: b.isTest === true,
  contact: {
    name: text(contact.name, 'nom', { required: true }),
    email: email ? email.toLowerCase() : null,
    company: text(contact.company, 'entreprise', { required: true }),
  },
  sector,
  goal: text(b.goal, 'objectif', { required: true, max: MAX.goal }),
  needs: sector ? listOf(b.needs, 'besoins', NEEDS[sector]) : [],
  details,
  scope: {
    languages: listOf(scope.languages, 'langues', LANGUAGES),
    budgetRaw: oneOf(scope.budgetRaw, 'budget', BUDGETS),
    budgetNumber: null, // kept for compatibility: Price parses the range itself
    deadline,
    notes: text(scope.notes, 'remarques', { max: MAX.notes }),
  },
};

return [{ json: { valid: errors.length === 0, errors, ...data } }];

