{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "description": "One sentence in French summarising what the prospect wants, using only what they wrote."
    },
    "projectType": {
      "type": "string",
      "enum": [
        "site_vitrine",
        "site_reservation",
        "e_commerce",
        "plateforme_immobiliere",
        "application_sur_mesure",
        "autre"
      ],
      "description": "The closest project type. Use 'autre' if none fits."
    },
    "features": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Concrete features explicitly requested (checked needs plus anything named in the free text). Short French phrases."
    },
    "wantsMotion3D": {
      "type": "boolean",
      "description": "True only if the prospect explicitly wants the website itself to have animation, motion, 3D or an immersive/premium visual experience. A 3D virtual tour of a property or product is a feature, not site design: list it in features and do NOT set this to true for it alone."
    },
    "integrations": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Third-party tools or platforms to connect (e.g. Instagram, CRM, Shopify). Empty if none mentioned."
    },
    "clarity": {
      "type": "string",
      "enum": ["claire", "partielle", "vague"],
      "description": "How clearly the prospect described their need. 'vague' if the goal is empty, meaningless or a few random characters."
    },
    "redFlags": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Problems worth checking before quoting: deadline in the past, impossible or unrealistically close; numbers that look impossible; contradictory or meaningless answers. Do NOT judge whether the budget is enough: pricing is handled elsewhere. Short French phrases. Empty if none."
    },
    "questionsToAsk": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Up to 3 short French questions to clarify the project before sending a final proposal. Empty if the request is clear."
    }
  },
  "required": [
    "summary",
    "projectType",
    "features",
    "wantsMotion3D",
    "integrations",
    "clarity",
    "redFlags",
    "questionsToAsk"
  ]
}

