// Price — Proposal Engine, stage 3
// Applies YOUR pricing grid to the assembled proposal, then turns the project
// value into a rental offer: a setup fee + a monthly fee, no commitment.
// The AI never sets a price: every number comes from PRICING below,
// so every quote can be explained line by line.
// Mode: Run Once for All Items · Language: JavaScript

// ---------------------------------------------------------------------------
// CONFIG — your pricing grid. Change numbers here, nowhere else.
// ---------------------------------------------------------------------------
const PRICING = {
  // Base price per project type (DH). null = "devis manuel": no automatic price.
  base: {
    site_vitrine: 12000,
    site_reservation: 18000,
    e_commerce: 25000,
    plateforme_immobiliere: 25000,
    application_sur_mesure: null,
    autre: null,
  },
  extraLanguage: 2500, // each language beyond the first
  feature: 2500,       // each requested feature not already included in the base
  integration: 2000,   // each third-party integration
  motionPercent: 30,   // added when the prospect wants motion/3D design
  rush: { underWeeks: 4, percent: 25 },
  floor: 8000,         // no project value goes below this

  // Rental model. The project value above is what the build is worth;
  // the client pays it as a setup fee + a monthly fee instead of all at once.
  rental: {
    setupPercent: 40,      // % of project value paid upfront (protects you: no commitment)
    amortizationMonths: 24, // the rest of the project value is spread over this many months
    maintenance: 300,      // added every month: maintenance, security, small content updates
    roundMonthlyTo: 50,
    includes: ['Maintenance et sécurité', 'Petites mises à jour de contenu'],
    excludes: ['Hébergement et nom de domaine (à la charge du client)'],
  },

  // Features already covered by a base price (matched by keyword, lowercase).
  // e.g. a booking site already includes booking, so it is not charged twice.
  includedFeatures: {
    site_reservation: ['réservation'],
    e_commerce: ['paiement', 'panier', 'commande'],
    plateforme_immobiliere: ['recherche', 'filtre'],
  },
};

// French labels for the proposal lines.
const TYPE_LABELS = {
  site_vitrine: 'Site vitrine sur mesure',
  site_reservation: 'Site avec réservation en ligne',
  e_commerce: 'Boutique en ligne',
  plateforme_immobiliere: 'Plateforme immobilière',
  application_sur_mesure: 'Application sur mesure',
  autre: 'Projet sur mesure',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// Percentage lines are rounded to the nearest 100 DH so the total stays clean.
const round100 = (n) => Math.round(n / 100) * 100;

// Removes duplicates case-insensitively, keeping the first spelling seen.
function dedupe(items) {
  const seen = new Set();
  return items.filter((item) => {
    const key = item.toLowerCase().trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

// Reads a budget option like "10 000 – 20 000 DH", "Moins de 10 000 DH"
// or "Plus de 40 000 DH" into { min, max }. max = null means no upper limit.
// Parses the numbers instead of matching exact strings, so a dash or space
// typed differently in the dropdown doesn't break it.
function parseBudget(raw) {
  if (!raw) return null;
  const numbers = (raw.match(/\d{1,3}(?:[\s\u00a0\u202f.]\d{3})+|\d+/g) || [])
    .map((n) => Number(n.replace(/\D/g, '')));
  const lower = raw.toLowerCase().trim();
  if (lower.startsWith('moins') && numbers.length) return { min: 0, max: numbers[0] };
  if (lower.startsWith('plus') && numbers.length) return { min: numbers[0], max: null };
  if (numbers.length >= 2) return { min: numbers[0], max: numbers[1] };
  return null;
}

// Number formatted the French way: 12500 -> "12 500 DH".
// toLocaleString('fr-FR') separates thousands with a NARROW no-break space (U+202F),
// which many fonts (Instrument Serif included) don't contain, so "12 800" printed as
// "12800". Swap it for a regular no-break space (U+00A0), which every font has and which
// still keeps the number on one line.
const frNumber = (n) => n.toLocaleString('fr-FR').replace(/\u202f/g, '\u00a0');
const dh = (n) => `${frNumber(n)}\u00a0DH`;

// ---------------------------------------------------------------------------
// Inputs (from "Assemble proposal")
// ---------------------------------------------------------------------------
const input = $input.first().json;
const lead = input.lead;
const req = input.requirements;

const lines = [];
const warnings = [];
const projectType = req.projectType;
const base = PRICING.base[projectType];
const manualQuote = base === null || base === undefined;

// ---------------------------------------------------------------------------
// Deadline (computed for every proposal, used for the rush fee)
// ---------------------------------------------------------------------------
const deadlineMs = Date.parse(lead.scope.deadline);
const submittedMs = Date.parse(lead.submittedAt);
let weeksToDeadline = null;
if (Number.isNaN(deadlineMs) || Number.isNaN(submittedMs)) {
  warnings.push('Date de lancement absente ou invalide : pas de majoration urgence appliquée.');
} else {
  weeksToDeadline = (deadlineMs - submittedMs) / (7 * 24 * 60 * 60 * 1000);
  if (weeksToDeadline < 0) {
    warnings.push('Date de lancement dans le passé : à clarifier avec le prospect.');
    weeksToDeadline = null;
  } else if (weeksToDeadline > 104) {
    // More than 2 years away is almost certainly a typo (e.g. year 20222).
    warnings.push('Date de lancement incohérente (plus de 2 ans) : à clarifier avec le prospect.');
    weeksToDeadline = null;
  }
}

let total = null;
let rushApplied = false;
let floorApplied = false;

if (manualQuote) {
  warnings.push(`Type de projet "${projectType}" : devis manuel requis, aucun prix automatique.`);
} else {
  // 1. Base
  lines.push({ label: TYPE_LABELS[projectType], amount: base, included: false });

  // 2. Languages: French counts as the primary language when present.
  const languages = dedupe(lead.scope.languages || []);
  const ordered = languages.includes('Français')
    ? ['Français', ...languages.filter((l) => l !== 'Français')]
    : languages;
  for (const language of ordered.slice(1)) {
    lines.push({ label: `Langue supplémentaire : ${language}`, amount: PRICING.extraLanguage, included: false });
  }

  // 3. Features and integrations.
  // A feature like "Intégration Instagram" is counted once, as an integration.
  const allFeatures = dedupe(req.features || []);
  const integrationFeatures = allFeatures.filter((f) => /intégration/i.test(f));
  const features = allFeatures.filter((f) => !/intégration/i.test(f));
  const integrations = dedupe([
    ...(req.integrations || []),
    ...integrationFeatures.map((f) => f.replace(/^intégration\s*/i, '')),
  ]);

  const includedKeywords = PRICING.includedFeatures[projectType] || [];
  for (const feature of features) {
    const included = includedKeywords.some((k) => feature.toLowerCase().includes(k));
    lines.push({
      label: `Fonctionnalité : ${feature}`,
      amount: included ? 0 : PRICING.feature,
      included,
    });
  }
  for (const integration of integrations) {
    lines.push({ label: `Intégration : ${integration}`, amount: PRICING.integration, included: false });
  }

  const subtotal = lines.reduce((sum, line) => sum + line.amount, 0);

  // 4. Motion / 3D design premium, on the subtotal.
  let motion = 0;
  if (req.wantsMotion3D) {
    motion = round100(subtotal * PRICING.motionPercent / 100);
    lines.push({ label: `Design animé / 3D (+${PRICING.motionPercent} %)`, amount: motion, included: false });
  }

  // 5. Rush fee, on everything above.
  if (weeksToDeadline !== null && weeksToDeadline < PRICING.rush.underWeeks) {
    const rush = round100((subtotal + motion) * PRICING.rush.percent / 100);
    lines.push({ label: `Délai court, moins de ${PRICING.rush.underWeeks} semaines (+${PRICING.rush.percent} %)`, amount: rush, included: false });
    rushApplied = true;
  }

  total = lines.reduce((sum, line) => sum + line.amount, 0);

  // 6. Floor
  if (total < PRICING.floor) {
    lines.push({ label: 'Ajustement au montant minimum', amount: PRICING.floor - total, included: false });
    total = PRICING.floor;
    floorApplied = true;
  }
}

// ---------------------------------------------------------------------------
// Budget check: price vs the range the prospect selected
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Rental offer: setup fee + monthly fee
// ---------------------------------------------------------------------------
let rental = null;
if (total !== null) {
  const R = PRICING.rental;
  const setupFee = round100(total * R.setupPercent / 100);
  const rawMonthly = (total - setupFee) / R.amortizationMonths + R.maintenance;
  const monthly = Math.ceil(rawMonthly / R.roundMonthlyTo) * R.roundMonthlyTo;
  rental = {
    setupFee,
    setupFeeLabel: dh(setupFee),
    monthly,
    monthlyLabel: `${dh(monthly)} / mois`,
    commitment: 'Sans engagement',
    includes: R.includes,
    excludes: R.excludes,
    // Internal: month at which you've recovered the full project value.
    breakEvenMonth: Math.ceil((total - setupFee) / (monthly - R.maintenance)),
  };
}

// ---------------------------------------------------------------------------
// Budget check: the monthly fee vs the monthly range the prospect selected
// ---------------------------------------------------------------------------
const budget = parseBudget(lead.scope.budgetRaw);
let budgetStatus = 'inconnu';
if (budget && rental) {
  if (budget.max !== null && rental.monthly > budget.max) budgetStatus = 'au_dessus';
  else if (rental.monthly < budget.min) budgetStatus = 'en_dessous';
  else budgetStatus = 'dans_budget';
}
if (budgetStatus === 'au_dessus') {
  warnings.push(`Mensualité (${rental.monthlyLabel}) au-dessus du budget indiqué (${lead.scope.budgetRaw}).`);
}

// ---------------------------------------------------------------------------
// Review gate: anything uncertain goes to you before it goes to the prospect
// ---------------------------------------------------------------------------
const needsReview =
  manualQuote ||
  req.clarity !== 'claire' ||
  (req.redFlags || []).length > 0 ||
  budgetStatus === 'au_dessus' ||
  warnings.length > 0;

return [
  {
    json: {
      ...input,
      pricing: {
        manualQuote,
        currency: 'DH',
        lines: lines.map((line) => ({ ...line, amountLabel: line.included ? 'Inclus' : dh(line.amount) })),
        // Project value: what the build is worth. Internal reference;
        // the client-facing offer is the rental below.
        total,
        totalLabel: total === null ? 'Sur devis' : dh(total),
        rental,
        rushApplied,
        floorApplied,
        weeksToDeadline: weeksToDeadline === null ? null : Math.round(weeksToDeadline * 10) / 10,
        budget: {
          raw: lead.scope.budgetRaw,
          min: budget ? budget.min : null,
          max: budget ? budget.max : null,
          status: budgetStatus,
        },
        warnings,
        needsReview,
      },
    },
  },
];

// Prepare document — Proposal Engine, stage 4
// Turns the priced proposal into ready-to-print French text for the PDF template.
// Two jobs:
//   1. Wording: internal labels become client-facing ones ("Fonctionnalité : X" -> "X").
//   2. Safety: everything the prospect typed is HTML-escaped. The PDF is rendered by a
//      real browser (Gotenberg/Chromium); unescaped input like <img src="http://..."> would
//      make that browser load whatever URL a stranger typed into your form.
// Mode: Run Once for All Items · Language: JavaScript

// ---------------------------------------------------------------------------
// CONFIG — your studio details, printed in the PDF footer. Fill these in.
// ---------------------------------------------------------------------------
const STUDIO = {
  name: 'CasaWebBuild',
  email: 'VOTRE_EMAIL',        // e.g. contact@yourdomain.com
  phone: 'VOTRE_TELEPHONE',    // e.g. +212 6 XX XX XX XX
  city: 'Casablanca',
};

// Title shown under "Votre projet", per project type.
const PROJECT_TITLES = {
  site_vitrine: 'Site vitrine sur mesure',
  site_reservation: 'Site avec réservation en ligne',
  e_commerce: 'Boutique en ligne sur mesure',
  plateforme_immobiliere: 'Plateforme immobilière sur mesure',
  application_sur_mesure: 'Application web sur mesure',
  autre: 'Projet web sur mesure',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// Makes any text safe to put inside HTML.
function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Capitalises the first letter (names typed in lowercase look careless on a proposal).
const capitalize = (s) => s.replace(/(^|\s|-)(\p{L})/gu, (m, sep, ch) => sep + ch.toUpperCase());

// The base price line is shown as the core work, not as the project type again
// (the project type is already the title of section 01).
const BASE_SCOPE_LABEL = 'Design et développement sur mesure';

// Pricing line label -> client-facing scope item. null = not shown to the client.
function scopeLabel(label, index) {
  if (index === 0) return BASE_SCOPE_LABEL;          // first line is always the base price
  if (label.startsWith('Ajustement')) return null;   // internal floor adjustment
  if (label.startsWith('Fonctionnalité : ')) return label.replace('Fonctionnalité : ', '');
  if (label.startsWith('Intégration : ')) return label.replace('Intégration : ', 'Intégration ');
  if (label.startsWith('Langue supplémentaire : ')) return `Version ${label.replace('Langue supplémentaire : ', '').toLowerCase()}`;
  if (label.startsWith('Design animé')) return 'Design animé et 3D sur mesure';
  if (label.startsWith('Délai court')) return 'Livraison accélérée';
  return label;
}

// ---------------------------------------------------------------------------
// Build the document fields
// ---------------------------------------------------------------------------
const input = $input.first().json;
const { lead, requirements: req, pricing } = input;

const issued = new Date(lead.submittedAt);
const dateLabel = [
  String(issued.getDate()).padStart(2, '0'),
  String(issued.getMonth() + 1).padStart(2, '0'),
  issued.getFullYear(),
].join('.');

const scopeItems = pricing.lines
  .map((line, index) => scopeLabel(line.label, index))
  .filter(Boolean);

const scopeHtml = scopeItems
  .map((item, i) => `<li><span class="num">${String(i + 1).padStart(2, '0')}</span><span>${esc(item)}</span></li>`)
  .join('');

const rental = pricing.rental;
const listHtml = (items) => items.map((item) => `<li>${esc(item)}</li>`).join('');

return [
  {
    json: {
      ...input,
      doc: {
        proposalId: esc(input.proposalId),
        dateLabel,
        validUntilLabel: esc(input.validUntilLabel),
        company: esc(capitalize(lead.contact.company || 'Votre entreprise')),
        name: esc(capitalize(lead.contact.name || '')),
        goal: esc(lead.goal || ''),
        projectTitle: esc(PROJECT_TITLES[req.projectType] || PROJECT_TITLES.autre),
        scopeHtml,
        manualQuote: pricing.manualQuote,
        // Monthly fee split in two so the template can set the number large.
        // Regular no-break space instead of the narrow one (see the note in Price).
        monthlyAmount: rental ? rental.monthly.toLocaleString('fr-FR').replace(/\u202f/g, '\u00a0') : 'Sur devis',
        monthlyUnit: rental ? 'DH / mois' : '',
        setupFeeLabel: rental ? esc(rental.setupFeeLabel) : '—',
        commitment: rental ? esc(rental.commitment) : '',
        includesHtml: rental ? listHtml(rental.includes) : '',
        excludesHtml: rental ? listHtml(rental.excludes) : '',
        studioName: esc(STUDIO.name),
        studioEmail: esc(STUDIO.email),
        studioPhone: esc(STUDIO.phone),
        studioCity: esc(STUDIO.city),
      },
    },
  },
];

// Build log row — Proposal Engine, stage 5a
// Shapes the proposal into exactly one row of the `proposals` table.
// Why a Code node instead of mapping fields in the Supabase node: here every value keeps
// its real type (numbers stay numbers, empty stays null, arrays stay arrays). Mapped
// expressions can turn a missing value into "" and Postgres rejects "" for an integer column.
// Mode: Run Once for All Items · Language: JavaScript

// Reads from "Price" by name: the nodes after it (HTML, file, PDF) no longer carry this data.
const p = $('Price').first().json;
const { lead, requirements: req, pricing } = p;

return [
  {
    json: {
      proposal_id: p.proposalId,
      is_test: lead.isTest === true,
      status: pricing.manualQuote ? 'devis_manuel' : 'en_attente',

      contact_name: lead.contact.name,
      contact_email: lead.contact.email,
      company: lead.contact.company,
      sector: lead.sector,
      goal: lead.goal,

      project_type: req.projectType,
      clarity: req.clarity,
      needs_review: pricing.needsReview,
      warnings: pricing.warnings,
      red_flags: req.redFlags,

      project_value: pricing.total,                         // null for manual quotes
      setup_fee: pricing.rental ? pricing.rental.setupFee : null,
      monthly_fee: pricing.rental ? pricing.rental.monthly : null,
      budget_raw: lead.scope.budgetRaw,
      budget_status: pricing.budget.status,
      valid_until: p.validUntil,

      payload: p,
    },
  },
];

// Approval email — Proposal Engine, stage 5b
// Writes the email YOU receive before anything reaches the prospect:
// a subject that tells you at a glance whether to look closely, and a body with
// the offer, the budget check and every warning, so you decide in 30 seconds.
// It also brings the PDF back: the nodes after "Render PDF" (log row, Supabase) dropped it.
// Mode: Run Once for All Items · Language: JavaScript

const p = $('Price').first().json;
const { lead, requirements: req, pricing } = p;

// French number with a regular no-break space as thousands separator.
const fr = (n) => n.toLocaleString('fr-FR').replace(/\u202f/g, '\u00a0');

const BUDGET_STATUS = {
  dans_budget: 'dans le budget',
  au_dessus: 'AU-DESSUS du budget',
  en_dessous: 'en dessous du budget',
  inconnu: 'budget non comparable',
};

// ---------------------------------------------------------------------------
// Subject: test flag, review flag, ID, company, offer
// ---------------------------------------------------------------------------
const tags = [];
if (lead.isTest) tags.push('[TEST]');
tags.push(pricing.manualQuote ? '[DEVIS MANUEL]' : pricing.needsReview ? '[À VÉRIFIER]' : '[OK]');

const offerShort = pricing.rental
  ? `${fr(pricing.rental.monthly)} DH/mois`
  : 'sur devis';

const subject = `${tags.join(' ')} ${p.proposalId} · ${lead.contact.company || 'Sans entreprise'} · ${offerShort}`;

// ---------------------------------------------------------------------------
// Body
// ---------------------------------------------------------------------------
const bullets = (items) => (items && items.length ? items.map((i) => `- ${i}`).join('\n') : '- aucun');

const lines = [
  `Proposition ${p.proposalId}`,
  '',
  `Prospect : ${lead.contact.name} <${lead.contact.email}>`,
  `Entreprise : ${lead.contact.company}`,
  `Secteur : ${lead.sector} · Type détecté : ${req.projectType}`,
  `Objectif : « ${lead.goal} »`,
  `Clarté de la demande : ${req.clarity}`,
  '',
];

if (pricing.rental) {
  lines.push(
    `Offre : ${fr(pricing.rental.setupFee)} DH de mise en place + ${fr(pricing.rental.monthly)} DH/mois, sans engagement`,
    `Valeur du projet : ${fr(pricing.total)} DH (rentabilisé au mois ${pricing.rental.breakEvenMonth})`,
  );
} else {
  lines.push('Offre : DEVIS MANUEL, aucun prix automatique.');
}

lines.push(
  `Budget indiqué : ${lead.scope.budgetRaw ?? 'non renseigné'} → ${BUDGET_STATUS[pricing.budget.status] || pricing.budget.status}`,
  `Lancement souhaité : ${lead.scope.deadline ?? 'non précisé'}${pricing.weeksToDeadline !== null ? ` (dans ${pricing.weeksToDeadline} semaines)` : ''}`,
  '',
  'Détail du prix :',
  bullets(pricing.lines.map((l) => `${l.label} : ${l.amountLabel}`)),
  '',
  'Avertissements :',
  bullets(pricing.warnings),
  '',
  "Points d'attention (IA) :",
  bullets(req.redFlags),
  '',
  'Questions à poser au prospect :',
  bullets(req.questionsToAsk),
);

if (lead.scope.notes) {
  lines.push('', `Remarques du prospect : ${lead.scope.notes}`);
}

return [
  {
    json: {
      proposalId: p.proposalId,
      manualQuote: pricing.manualQuote,
      subject,
      body: lines.join('\n'),
    },
    // The PDF from "Render PDF", so it can be attached again.
    binary: $('Render PDF').first().binary,
  },
];

// Prospect email — Proposal Engine, stage 5c
// Writes the email the prospect receives with their PDF, after you clicked "Envoyer".
// Safety: on a TEST run the email goes to YOU, never to the address typed in the form.
// Mode: Run Once for All Items · Language: JavaScript

// ---------------------------------------------------------------------------
// CONFIG
// ---------------------------------------------------------------------------
const OWNER_EMAIL = 'YOUR_EMAIL@example.com';        // test runs are sent here instead of to the prospect
const SIGNATURE = [
  'CasaWebBuild',
  'Sites web sur mesure — Casablanca',
  'YOUR_PHONE',
].join('\n');
const MAX_QUESTIONS = 2;                  // questions from the AI included in the email

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const p = $('Price').first().json;
const { lead, requirements: req, pricing } = p;
const fr = (n) => n.toLocaleString('fr-FR').replace(/\u202f/g, '\u00a0');
const capitalize = (s) => s.replace(/(^|\s|-)(\p{L})/gu, (m, sep, ch) => sep + ch.toUpperCase());

const firstName = capitalize((lead.contact.name || '').trim().split(/\s+/)[0] || '');
const company = capitalize(lead.contact.company || 'votre entreprise');
const isTest = lead.isTest === true;

// ---------------------------------------------------------------------------
// Email
// ---------------------------------------------------------------------------
const subject = `${isTest ? '[TEST] ' : ''}Votre proposition CasaWebBuild — ${company}`;

const lines = [
  firstName ? `Bonjour ${firstName},` : 'Bonjour,',
  '',
  `Merci pour votre demande. Vous trouverez en pièce jointe la proposition préparée pour ${company}.`,
  '',
  `En résumé : ${fr(pricing.rental.setupFee)} DH de mise en place, puis ${fr(pricing.rental.monthly)} DH par mois, sans engagement. La maintenance et les petites mises à jour sont comprises.`,
];

const questions = (req.questionsToAsk || []).slice(0, MAX_QUESTIONS);
if (questions.length) {
  lines.push(
    '',
    'Pour affiner le projet, deux points m\'aideraient :',
    ...questions.map((q) => `- ${q}`),
  );
}

lines.push(
  '',
  `Pour accepter, répondez simplement à cet email : je vous recontacte pour lancer le projet. La proposition est valable jusqu'au ${p.validUntilLabel}.`,
  '',
  'À très vite,',
  SIGNATURE,
);

return [
  {
    json: {
      proposalId: p.proposalId,
      to: isTest ? OWNER_EMAIL : lead.contact.email,
      subject,
      body: lines.join('\n'),
    },
    // The PDF again: "Ask approval" outputs only your answer, not the file.
    binary: $('Render PDF').first().binary,
  },
];
